import hashlib
import hmac
import secrets
from typing import Tuple

from app.core.config import settings

# Prefix identifying keys generated by OmniGraph
KEY_PREFIX_BASE = "ogr_live_"


def hash_api_key(key: str) -> str:
    """
    Produce a deterministic HMAC-SHA256 digest of the raw API key.
    
    Security Reasoning:
    High-entropy machine tokens (>= 256 bits of cryptographically secure entropy)
    do not suffer from dictionary or rainbow table attacks that target human passwords.
    HMAC-SHA256 using the server's SECRET_KEY provides:
    1. Sub-millisecond lookup latency, essential for high-throughput API endpoints.
    2. Protection against database leaks: without SECRET_KEY, an attacker cannot
       verify or generate key digests.
    3. Immunity to length-extension attacks.
    4. Safe constant-time comparison via hmac.compare_digest.
    """
    return hmac.new(
        settings.SECRET_KEY.encode("utf-8"),
        key.encode("utf-8"),
        hashlib.sha256
    ).hexdigest()


def generate_api_key() -> Tuple[str, str, str]:
    """
    Generate a cryptographically secure tenant API key.
    
    Returns:
        (full_secret_key, key_prefix, key_hash)
        
    Format:
        ogr_live_<8-hex-prefix>_<32-char-random-secret>
        Example: ogr_live_a82f9d12_7kQ1wZ8pLmNxTy...
    """
    # 8-char random prefix for identification and indexing
    prefix_token = secrets.token_hex(4)
    key_prefix = f"{KEY_PREFIX_BASE}{prefix_token}"
    
    # High-entropy random payload (24 bytes urlsafe -> 32 characters)
    secret_token = secrets.token_urlsafe(24)
    full_key = f"{key_prefix}_{secret_token}"
    
    key_hash = hash_api_key(full_key)
    return full_key, key_prefix, key_hash


def mask_api_key(key_prefix: str) -> str:
    """
    Return a masked representation of the API key for safe UI display.
    Example: ogr_live_a82f••••••••
    """
    return f"{key_prefix}••••••••"


def verify_api_key(raw_key: str, expected_hash: str) -> bool:
    """Constant-time verification of an API key against its stored HMAC hash."""
    computed_hash = hash_api_key(raw_key)
    return hmac.compare_digest(computed_hash, expected_hash)
